import { MakeLogicType, afterMount, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { dataWarehouseTotalRowsStatsRetrieve } from 'products/data_warehouse/frontend/generated/api'
import type { TotalRowsStatsResponseApi } from 'products/data_warehouse/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface billingRowStatsLogicValues {
    billingRowStats: TotalRowsStatsResponseApi | null
    billingRowStatsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface billingRowStatsLogicActions {
    loadBillingRowStats: () => any
    loadBillingRowStatsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadBillingRowStatsSuccess: (
        billingRowStats: TotalRowsStatsResponseApi | null,
        payload?: any
    ) => {
        billingRowStats: TotalRowsStatsResponseApi | null
        payload?: any
    }
}

export type billingRowStatsLogicType = MakeLogicType<billingRowStatsLogicValues, billingRowStatsLogicActions>

export const billingRowStatsLogic = kea<billingRowStatsLogicType>([
    path(['products', 'data_warehouse', 'frontend', 'shared', 'logics', 'billingRowStatsLogic']),
    loaders(() => ({
        billingRowStats: [
            null as TotalRowsStatsResponseApi | null,
            {
                loadBillingRowStats: async () => {
                    const { currentTeamId } = teamLogic.values
                    if (!currentTeamId) {
                        return null
                    }
                    return await dataWarehouseTotalRowsStatsRetrieve(currentTeamId.toString())
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadBillingRowStats()
    }),
])
